axes.find:
CWwdGameObjectA* h = m_object;
i32 outX = h->m_extent.left;
i32 spanX = abs(h->m_extent.right - outX);
i32 outY = h->m_extent.top;
i32 spanY = abs(h->m_extent.bottom - outY);
if (spanX != 0) {
    outX += GruntRand() % spanX;
}
if (spanY != 0) {
    outY += GruntRand() % spanY;
}

